def solve_n_queens(n):
    result = []
    def is_valid(board, row, col):
        for i in range(row):
            if board[i] == col or abs(board[i] - col) == row - i:
                return False
        return True

    def backtrack(board, row):
        if row == n:
            result.append(board[:])
            return
        for col in range(n):
            if is_valid(board, row, col):
                board.append(col)
                backtrack(board, row + 1)
                board.pop()

    backtrack([], 0)
    return len(result)

