from collections import deque

def level_order(root):
    if not root:
        return []
    result = []
    queue = deque([root])
    while queue:
        level = []
        for _ in range(len(queue)):
            node = queue.popleft()
            level.append(node['val'])
            if node.get('left'):
                queue.append(node['left'])
            if node.get('right'):
                queue.append(node['right'])
        result.append(level)
    return result

